definition.script:
node {
  stage('checkout') { git url: 'http://gitea:3000/ci/stoa-labs.git', branch: 'main' }
  stage('app-request') {
    // Traçabilité : l'identité Jenkins du demandeur remplace oig-/cli2-provisioner.
    // getBuildCauses est approuvé en sandbox. PIÈGE constaté à l'exécution : sur un
    // déclenchement anonyme, userId vaut JSON null MAIS getBuildCauses le rend sous
    // forme d'un objet JSONNull non-null (net.sf.json), donc VRAI pour Groovy — un
    // simple `cause[0].userId ? ... : 'anonymous'` retombe alors sur la chaîne
    // littérale "null" au lieu de 'anonymous'. On force la comparaison en texte.
    def cause = currentBuild.getBuildCauses('hudson.model.Cause$UserIdCause')
    def rawUid = (cause && !cause.isEmpty()) ? "${cause[0].userId}" : 'anonymous'
    def uid = (rawUid == 'null' || rawUid == '') ? 'anonymous' : rawUid
    // API v2 (Task 4, P3) : la liste déroulante porte "nom@version" (généré par
    // scripts/lib/generate-choices.sh) — scindé ICI, jamais dans provision-request.sh
    // (qui continue de recevoir REQ_API/REQ_API_VER séparés, forme inchangée pour
    // les voies machine OIG/CLI2). Premier '@' : name/version restent tous deux
    // dans [A-Za-z0-9._-] (garde du script), donc jamais de '@' interne à lever.
    def apiChoice = params.API ?: ''
    def atIdx = apiChoice.indexOf('@')
    def reqApi = atIdx >= 0 ? apiChoice.substring(0, atIdx) : apiChoice
    def reqApiVer = atIdx >= 0 ? apiChoice.substring(atIdx + 1) : '1.0.0'
    withCredentials([string(credentialsId: 'gitea-provision-token', variable: 'GITEA_TOKEN')]) {
      // Les paramètres passent par l'ENVIRONNEMENT, jamais interpolés dans la
      // chaîne sh : saisie humaine = donnée d'un tiers (même règle que
      // team-request/provision-apply). MODE explicite prime toujours sur la
      // dérivation par REQ_CALLER dans provision-request.sh. Les champs Task 4
      // (TEAM/IP_ALLOWLIST/CERT_PEM/CERT_ROTATION) sont TOUS optionnels côté
      // script — un formulaire qui les laisse vides reproduit le comportement
      // d'avant Task 4, octet pour octet (cf. provision-request.sh).
      withEnv(["REQ_APP=${params.APP}", "REQ_ENV=${params.REQ_ENV}",
               "REQ_API=${reqApi}", "REQ_API_VER=${reqApiVer}",
               "REQ_CLIENT_ID=${params.CLIENT_ID ?: ''}", "REQ_MODE=${params.MODE}",
               "REQ_TEAM=${params.TEAM ?: ''}",
               "REQ_IP_ALLOWLIST=${params.IP_ALLOWLIST ?: ''}",
               "REQ_CERT_PEM=${params.CERT_PEM ?: ''}",
               "REQ_CERT_ROTATION=${params.CERT_ROTATION ?: 'replace'}",
               "REQ_CALLER=jenkins-form:${uid}"]) {
        dir('poc-control-plane-federation') { sh 'set +x; bash scripts/provision-request.sh' }
      }
    }
  }
}
